import os
import tarfile
from pathlib import Path

def extract_files(tar_file):
    tar = tarfile.open(tar_file)
    tar.extractall(path="/tmp")
    tar.close()

def check_files(tar_file):
    tar = tarfile.open(tar_file)
    tar.extractall(path="/tmp")
    tar.close()

    for file in Path("/tmp").iterdir():
        if file.is_file():
            print(f"Found file: {file}")

def main():
    extract_files("data.tar.gz")
    check_files("data.tar.gz")

if __name__ == "__main__":
    main()

